/**
 * The world as the "countries visited" feature counts it: 193 UN member
 * states plus Vatican City and Palestine = 195, the same denominator as
 * NomadTable's "n/195 countries". Names and label points come from Natural
 * Earth (public domain); `dot: true` marks states too small for the 110 m
 * polygon set, drawn as a point on the globe instead.
 *
 * GENERATED by scratchpad/gen_countries.py. Edit the script, not this file.
 */
export interface Country {
  /** ISO 3166-1 alpha-2, upper case. */
  code: string;
  name: string;
  /** Label point (WGS84), used to fly to the country and for the dot marker. */
  lng: number;
  lat: number;
  /** No polygon in the bundled 110 m set: render as a dot. */
  dot?: boolean;
}

