const BY_CODE: ReadonlyMap<string, Country> = new Map(COUNTRIES.map((c) => [c.code, c]));

export function countryByCode(code: string): Country | undefined {
  return BY_CODE.get(code.toUpperCase());
}

export function isCountryCode(code: string): boolean {
  return BY_CODE.has(code.toUpperCase());
}

/** Regional-indicator flag emoji for an alpha-2 code ("VN" → 🇻🇳). */
export function flagEmoji(code: string): string {
  const up = code.toUpperCase();
  if (!/^[A-Z]{2}$/.test(up)) return "🏳️";
  return String.fromCodePoint(...[...up].map((ch) => 0x1f1e6 + ch.charCodeAt(0) - 65));
}

/** "1.5" for 3 of 195, one decimal, never "0.0" when at least one is set. */
export function worldPercent(count: number): string {
  if (count <= 0) return "0";
  const pct = (count / WORLD_COUNTRY_COUNT) * 100;
  return pct < 0.1 ? "0.1" : pct >= 10 ? String(Math.round(pct)) : pct.toFixed(1);
}

/** Case- and accent-insensitive name search; also matches the code itself. */
export function searchCountries(query: string, limit = 8): Country[] {
  const q = fold(query.trim());
  if (!q) return [];
  const starts: Country[] = [];
  const contains: Country[] = [];
  for (const c of COUNTRIES) {
    const n = fold(c.name);
    if (n.startsWith(q) || c.code.toLowerCase() === q) starts.push(c);
    else if (n.includes(q)) contains.push(c);
  }
  return [...starts, ...contains].slice(0, limit);
}

function fold(s: string): string {
  return s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
}
